"""Every case in conformance/pricing.v1.json, generated by the TypeScript reference."""
import json
import unittest
from pathlib import Path

from super_router import RouterError, bound, charge, compile_credit_price

CASES = json.loads((Path(__file__).resolve().parents[3] / "conformance" / "pricing.v1.json").read_text())


def run(fn):
    try:
        value = fn()
        return {"ok": str(value) if isinstance(value, int) else value}
    except RouterError as e:
        return {"error": e.code}


class Conformance(unittest.TestCase):
    def test_charge(self):
        for i, case in enumerate(CASES["charge"]):
            with self.subTest(i=i):
                self.assertEqual(run(lambda: charge(case["usage"], case["price"])), case["expect"])

    def test_bound(self):
        for i, case in enumerate(CASES["bound"]):
            with self.subTest(i=i):
                self.assertEqual(run(lambda: bound(case["input"], case["output"], case["price"])), case["expect"])

    def test_compile_credit_price(self):
        for i, case in enumerate(CASES["compile_credit_price"]):
            with self.subTest(i=i):
                self.assertEqual(run(lambda: compile_credit_price(case["config"])), case["expect"])

    def test_case_counts(self):
        self.assertGreaterEqual(len(CASES["charge"]), 100)
        errors = [c for k in ("charge", "bound", "compile_credit_price") for c in CASES[k] if "error" in c["expect"]]
        self.assertGreater(len(errors), 20)


if __name__ == "__main__":
    unittest.main()
